with gaps as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval '1' hour then 1 else 0 end as session_start_flag from device_readings) select id, device_code, reading_ts, humidity, pressure, status_bits, sum(session_start_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from gaps
